import {test} from 'node:test';
import assert from 'node:assert/strict';
import {runCapacity,LIMITS,SCOPE,ALL_KINDS} from '../scripts/measure-case-bundle-capacity.mjs';

// Small, fast configuration of the same Node-side measurement. Full-size evidence lives in
// docs/evidence/2026-10-15-case-bundle-capacity-node.json (generated by the script).
test('small capacity configuration validates schema, round-trip and over-limit refusals',async()=>{
 const report=await runCapacity({kinds:['elastic','thermal'],cases:2,views:2,measurements:2,configuration:'small'});
 assert.equal(report.schemaVersion,1);
 assert.equal(report.scope,'node; shared modules; not browser UI, not network');
 assert.equal(SCOPE,report.scope);
 assert.deepEqual(report.limits,{maxCases:8,maxViews:16,maxMeasurements:100,maxMeasurementArchiveBytes:300000,chunkBytes:65536,maxBundleBytes:100000000});
 assert.ok(ALL_KINDS.length>=9);
 assert.equal(report.kinds.length,2);
 assert.equal(report.summary.status,'pass',JSON.stringify(report.kinds.map(k=>k.error)));
 for(const k of report.kinds){
  assert.equal(k.status,'pass');
  assert.ok(['elastic','thermal'].includes(k.resultKind));
  assert.equal(k.verification.hashEqual,true);
  assert.equal(k.verification.restoredEqualsBuilt,true);
  assert.equal(k.verification.archiveRevisionEqual,true);
  assert.deepEqual(k.verification.counts,{cases:2,views:2,measurements:2});
  assert.equal(k.verification.restoredViewFields.mismatches,0);
  assert.ok(k.bytes.bundle>0&&k.transfer.chunks===Math.ceil(k.bytes.bundle/LIMITS.chunkBytes));
  assert.ok(k.wallMs>0&&k.memory.peakRssBytes>0&&k.memory.peakHeapUsedBytes>0);
  assert.equal(k.distinctPhysicalOutputs,1);
 }
 const names=report.refusals.checks.map(c=>c.name);
 for(const required of ['ninth case added to a full store','9-case bundle import','17-view bundle import','101-measurement bundle import','oversize chunk (65537 bytes) write','declared hash differs from content','content byte flipped after hashing','stale expected archive revision'])assert.ok(names.includes(required),required);
 assert.equal(report.refusals.allRefused,true,JSON.stringify(report.refusals.checks.filter(c=>!c.refused||!c.matchesDocumentedMessage)));
 for(const c of report.refusals.checks)if('stateUnchanged' in c)assert.equal(c.stateUnchanged,true,c.name);
 assert.match(report.refusals.checks.find(c=>c.name==='ninth case added to a full store').actualMessage,/Maximum 8 cases/);
 assert.match(report.refusals.checks.find(c=>c.name==='declared hash differs from content').actualMessage,/hash mismatch/);
 await assert.rejects(runCapacity({kinds:['elastic'],cases:9}),/exceeds documented limits/);
 const skipped=await runCapacity({kinds:['unknownKind'],cases:1,views:1,measurements:0,configuration:'small'});
 assert.equal(skipped.kinds[0].status,'skipped');assert.ok(skipped.kinds[0].reason);assert.equal(skipped.summary.status,'fail');
});
